    private fun decode(hex: String): FloatArray {
        val out = FloatArray(hex.length / 2)
        for (i in out.indices) out[i] = Integer.parseInt(hex.substring(2 * i, 2 * i + 2), 16) / 100f
        return out
    }

    private val matte by lazy { decode(MATTE) }
    private val glossy by lazy { decode(GLOSSY) }
    private val plain by lazy { decode(PLAIN) }
    private val matteHi by lazy { decode(MATTE_HI) }
    private val glossyHi by lazy { decode(GLOSSY_HI) }
    private val plainHi by lazy { decode(PLAIN_HI) }

    /** media 0 = plain (4 inks), 1 = glossy photo, 2 = matte photo (3 inks); high = Canon's High quality. */
    fun table(media: Int, high: Boolean): FloatArray = when (media) {
        1 -> if (high) glossyHi else glossy
        2 -> if (high) matteHi else matte
        else -> if (high) plainHi else plain
    }
}
